/* global WebImporter */

// AUTO-GENERATED by tools/importer/gen-import-scripts.mjs — one script per template.
// Orchestrates block parsers + site-wide transformers (cleanup -> links -> sections).

// PARSER IMPORTS
import carouselParser from './parsers/carousel.js';
import tableOverviewParser from './parsers/table-overview.js';
import tabsParser from './parsers/tabs.js';

// TRANSFORMER IMPORTS
import cleanupTransformer from './transformers/wknd-cleanup.js';
import linksTransformer from './transformers/wknd-links.js';
import sectionsTransformer from './transformers/wknd-sections.js';

// PARSER REGISTRY
const parsers = {
  'carousel': carouselParser,
  'table-overview': tableOverviewParser,
  'tabs': tabsParser,
};

// Category membership per adventure slug — the authoritative set captured from
// the live source's "Current Adventures" filter tabs (mirrors SLUG_CATEGORIES in
// parsers/cards.js). Injected as a "Category" metadata row on each detail page so
// the adventures query-index exposes a `category` column; the dynamic
// adventure-cards block + tabs-filter read categories from the index rather than
// a hard-coded JS map. Untagged adventures (e.g. cycling-southern-utah) get no
// category and therefore only appear under "All".
const SLUG_CATEGORIES = {
  'bali-surf-camp': ['Surfing'],
  'beervana-portland': ['Travel'],
  'climbing-new-zealand': ['Climbing'],
  'colorado-rock-climbing': ['Climbing'],
  'cycling-tuscany': ['Cycling', 'Travel'],
  'downhill-skiing-wyoming': ['Skiing'],
  'gastronomic-marais-tour': ['Travel'],
  'napa-wine-tasting': ['Travel'],
  'riverside-camping-australia': ['Travel'],
  'ski-touring-mont-blanc': ['Skiing'],
  'surf-camp-costa-rica': ['Surfing'],
  'tahoe-skiing': ['Skiing'],
  'west-coast-cycling': ['Cycling'],
  'whistler-mountain-biking': ['Cycling'],
  'yosemite-backpacking': ['Travel'],
};

// Author-controlled display order per adventure slug. The dynamic adventure-cards
// block sorts by this ascending, then applies its `limit` — so the homepage teaser
// (limit 4) shows orders 1–4, and raising the limit to 5 pulls in order 5, etc.
// Injected as an "Order" metadata row so the query-index exposes an `order` column.
// Values seeded to the original alphabetical display order (1-based); change a
// page's number to move it in the teaser/listing without touching code.
const SLUG_ORDER = {
  'bali-surf-camp': 1,
  'beervana-portland': 2,
  'climbing-new-zealand': 3,
  'colorado-rock-climbing': 4,
  'cycling-southern-utah': 5,
  'cycling-tuscany': 6,
  'downhill-skiing-wyoming': 7,
  'gastronomic-marais-tour': 8,
  'napa-wine-tasting': 9,
  'riverside-camping-australia': 10,
  'ski-touring-mont-blanc': 11,
  'surf-camp-costa-rica': 12,
  'tahoe-skiing': 13,
  'west-coast-cycling': 14,
  'whistler-mountain-biking': 15,
  'yosemite-backpacking': 16,
};

// Optional short card blurb per adventure slug, shown on the listing/teaser
// cards instead of the full page description. Seeded from the live source's card
// teasers where they differ from the article's og:description — e.g. Riverside
// Camping shows "Siegel River Australia" on the card but a longer description on
// the page. Slugs omitted here fall back to the og:description. Injected as a
// "Card Description" metadata row feeding the query-index `cardDescription`.
const SLUG_CARD_DESCRIPTION = {
  'riverside-camping-australia': 'Siegel River Australia',
};

/**
 * Append a `<tr><td>key</td><td>value</td></tr>` row to the Metadata block that
 * WebImporter.rules.createMetadata produced. createMetadata emits a <table> whose
 * header cell reads "Metadata" (the `.metadata` class only appears after the
 * md2da conversion, so match by header text here). No-op if the value is empty
 * or the metadata table isn't found.
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} key the metadata key (becomes a `<meta name="key">`)
 * @param {string} value the metadata value
 */
function appendMetadataRow(main, document, key, value) {
  if (!value) return;
  const metaTable = [...main.querySelectorAll('table')].reverse().find((t) => {
    const head = t.querySelector('th, td');
    return head && head.textContent.trim().toLowerCase() === 'metadata';
  });
  if (!metaTable) return;

  const tr = document.createElement('tr');
  const keyCell = document.createElement('td');
  keyCell.textContent = key;
  const valCell = document.createElement('td');
  valCell.textContent = value;
  tr.append(keyCell, valCell);
  metaTable.append(tr);
}

/**
 * Append a "Category" row to the Metadata block, using the adventure slug from
 * the page URL. Becomes a `<meta name="category">` feeding the query-index
 * `category` column. Untagged adventures get no row (shown only under "All").
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} originalURL the source page URL
 */
function injectCategoryMetadata(main, document, originalURL) {
  const slug = new URL(originalURL).pathname.match(/\/adventures\/([^./?#]+)/)?.[1];
  const cats = (slug && SLUG_CATEGORIES[slug]) || [];
  appendMetadataRow(main, document, 'Category', cats.join(', '));
}

/**
 * Append an "Order" row to the Metadata block, using the adventure slug from the
 * page URL. Becomes a `<meta name="order">` feeding the query-index `order`
 * column, which the adventure-cards block sorts by before applying its limit.
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} originalURL the source page URL
 */
function injectOrderMetadata(main, document, originalURL) {
  const slug = new URL(originalURL).pathname.match(/\/adventures\/([^./?#]+)/)?.[1];
  const order = slug && SLUG_ORDER[slug];
  appendMetadataRow(main, document, 'Order', order ? String(order) : '');
}

/**
 * Append a "Card Description" row to the Metadata block, using the adventure
 * slug from the page URL. Becomes a `<meta name="card-description">` feeding the
 * query-index `cardDescription` column, which the adventure-cards block prefers
 * over the full description when rendering a card blurb.
 * @param {Element} main document.body after createMetadata has run
 * @param {Document} document
 * @param {string} originalURL the source page URL
 */
function injectCardDescriptionMetadata(main, document, originalURL) {
  const slug = new URL(originalURL).pathname.match(/\/adventures\/([^./?#]+)/)?.[1];
  appendMetadataRow(main, document, 'Card Description', (slug && SLUG_CARD_DESCRIPTION[slug]) || '');
}

